import { STELLAR_CLASSES } from './stellar-physics.js';
import { installAttachmentControls } from './attachment-ui.js';
const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
const link=(url,label)=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`;
const fmt=n=>Number.isFinite(n)?n.toLocaleString(undefined,{maximumSignificantDigits:5}):'—';
const massLog=v=>Math.log10(Math.max(1e-6,v)),radiusLog=v=>Math.log10(Math.max(.01,v));
const omegaLog=v=>Math.sign(v)*Math.log10(1+Math.abs(v)/1e-8),omegaValue=v=>Math.sign(v)*1e-8*(10**Math.abs(v)-1);
export function installStellarControls(api){
 const mount=document.createElement('section');mount.className='stellar-controls';mount.hidden=true;api.container.prepend(mount);const attachments=installAttachmentControls(api);
 const classes=Array.isArray(STELLAR_CLASSES)?STELLAR_CLASSES:Object.entries(STELLAR_CLASSES).map(([id,v])=>({id,...v}));
 const range=(key,label,min,max,step)=>`<div class="stellar-range"><div class="range-header"><label for="stellar-${key}">${label}</label><output id="stellar-${key}-value"></output></div><div class="stellar-slider"><input id="stellar-${key}" type="range" min="${min}" max="${max}" step="${step}"><i id="stellar-${key}-threshold" hidden></i></div><input id="stellar-${key}-exact" type="number" step="any" aria-label="Exact ${label}"></div>`;
 mount.innerHTML=`<style>.stellar-controls{margin:0 0 18px;padding:14px;border:1px solid #35546d;border-radius:8px;background:#0a1927}.stellar-controls[hidden]{display:none}.stellar-controls h4{margin:0 0 12px;font-size:12px;color:#cbe7f8}.stellar-controls select,.stellar-controls input[type=number]{width:100%;min-height:36px;background:#09131e;color:#d2eafa;border:1px solid #304c63;border-radius:5px;padding:7px;font:12px ui-monospace,monospace}.stellar-range{margin:15px 0}.stellar-slider{position:relative}.stellar-slider input{width:100%}.stellar-slider i{position:absolute;width:2px;height:15px;background:#edbe75;top:5px;pointer-events:none;box-shadow:0 0 5px #edbe7566}.stellar-readout{font:11px ui-monospace,monospace;line-height:1.7;color:#9fc3db}.stellar-threshold{border-left:2px solid #dcb16f;padding-left:9px;font-size:11px;color:#d9c6a7;line-height:1.6}.stellar-status{font-size:10px;letter-spacing:1px;color:#b5d9ef;margin-top:10px}.stellar-controls .toggle-line{font-size:11px}</style>
 <style>.stellar-interior{margin:14px 0;padding:12px;border:1px solid #744c39;border-radius:6px;background:#211714}.stellar-interior[hidden]{display:none}.stellar-interior h5{margin:0;color:#ffd3aa;font-size:11px;letter-spacing:.06em}.stellar-interior svg{display:block;width:100%;height:auto;margin:5px 0}.stellar-interior text{font:10px system-ui,sans-serif;fill:#e5c3a5}.stellar-interior dl{display:grid;grid-template-columns:1fr auto;gap:5px 9px;font-size:11px;margin:8px 0}.stellar-interior dt{color:#c9a98e}.stellar-interior dd{margin:0;text-align:right;color:#f3d8bc;font-variant-numeric:tabular-nums}.stellar-interior p{font-size:11px;line-height:1.55;color:#c9b3a2;margin:8px 0 0}.stellar-interior a{color:#aad8ed}.stellar-interior .stellar-interior-scale{color:#e7bc8f;font-size:9px;text-transform:uppercase;letter-spacing:.06em}</style>
 <h4>STAR · MASS, RADIUS & SPIN</h4><label class="field-label" for="stellar-class">STELLAR CLASS</label><select id="stellar-class">${classes.map(c=>`<option value="${c.id}">${c.label||c.name||c.id}</option>`).join('')}</select>
 <aside class="stellar-interior" id="stellar-interior" hidden aria-label="Thorne–Żytkow Object interior">
  <h5>ONE STAR · A CENTERED NEUTRON CORE</h5>
  <svg viewBox="0 0 270 104" role="img" aria-label="Schematic cutaway: a tiny neutron-star core inside a red-supergiant envelope. Not to scale."><defs><radialGradient id="tzo-envelope"><stop offset="0" stop-color="#f4b478"/><stop offset=".65" stop-color="#b85c34"/><stop offset="1" stop-color="#663424"/></radialGradient></defs><circle cx="54" cy="52" r="43" fill="url(#tzo-envelope)" stroke="#dc9866"/><circle cx="54" cy="52" r="6" fill="#d4ecff" stroke="#fff"/><path d="M60 52H111M85 23H111" stroke="#c8a58b" fill="none"/><text x="117" y="26">Red-supergiant envelope</text><text x="117" y="55">Neutron-star core</text><text x="117" y="76">Hidden by opaque gas</text></svg>
  <div class="stellar-interior-scale">Schematic cutaway · core enlarged · not to scale</div>
  <dl><dt>Total stellar mass</dt><dd id="stellar-interior-total"></dd><dt>Included core mass</dt><dd id="stellar-interior-core"></dd><dt>Envelope mass</dt><dd id="stellar-interior-envelope"></dd><dt>Reference core radius</dt><dd id="stellar-interior-radius"></dd></dl>
  <p id="stellar-interior-note"></p><p>A hypothetical stellar merger product. Envelope opacity reveals a diagnostic cutaway: the luminous core marker is enlarged to 22% of the envelope radius. The real envelope hides a 12-km core; this is not a zero-radius orbit or a second gravitating object. ${link('https://arxiv.org/abs/2410.02896','TŻO review · O’Grady et al.')}</p>
 </aside>
 ${range('mass','Mass M · solar masses',-6,12,.005)}${range('radius','Radius R · meters',-2,15,.005)}${range('omega','Angular velocity Ω · rad/s',-13,13,.005)}
 <p class="stellar-readout" id="stellar-spin"></p><p class="stellar-threshold" id="stellar-threshold-note"></p><p class="stellar-status" id="stellar-state"></p>
 <label class="toggle-line"><span>Cycle radius · collapse comparison</span><input id="stellar-cycle" type="checkbox" role="switch"></label><p class="control-note">The reverse half of the cycle is a visualization, not a physical black hole turning back into a star. Mass, rotation, pressure, and matter physics all affect real collapse.</p>`;
 const $=id=>mount.querySelector('#'+id);let selected=null,raf=0,pending=null;
 const hiddenGeneric=['editMassSolar','editRadiusMeters','editRotation','editBodyStyle'];
 function patch(value){if(!selected)return;const renderer=api.renderer(),sceneId=renderer?.sceneId,prior=pending?.id===selected&&pending.renderer===renderer&&pending.sceneId===sceneId?{...pending}:{};if(value.starStyle)for(const key of Object.keys(STELLAR_CLASSES[value.starStyle]||{}))delete prior[key];pending={...prior,id:selected,renderer,sceneId,...value};if(raf)return;raf=requestAnimationFrame(()=>{raf=0;const next=pending;pending=null;if(!next||next.id!==selected||next.renderer!==api.renderer()||next.sceneId!==api.renderer()?.sceneId)return;const {id,renderer,sceneId,...properties}=next;renderer?.updateStellar?.(id,properties);api.changed();update(id);});}
 const specs={mass:['massSolar',massLog,x=>10**x],radius:['radiusMeters',radiusLog,x=>10**x],omega:['angularVelocity',omegaLog,omegaValue]};
 for(const [key,[property,,inverse]] of Object.entries(specs)){
  $('stellar-'+key).addEventListener('input',()=>patch({[property]:inverse(Number($('stellar-'+key).value)),...(key==='radius'?{collapseEnabled:false}:{})}));
  $('stellar-'+key+'-exact').addEventListener('change',()=>{const n=Number($('stellar-'+key+'-exact').value);if(Number.isFinite(n)&&(key==='omega'||n>0))patch({[property]:n,...(key==='radius'?{collapseEnabled:false}:{})});else update(selected);});
 }
 $('stellar-class').addEventListener('change',()=>patch({starStyle:$('stellar-class').value,collapseEnabled:false}));$('stellar-cycle').addEventListener('change',()=>patch({collapseEnabled:$('stellar-cycle').checked}));
 function update(id){
  attachments.update(id);const r=api.renderer(),object=r?.objects?.find(o=>o.id===id),show=object?.type==='star';selected=show?id:null;mount.hidden=!show;
  for(const key of hiddenGeneric){const input=document.getElementById(key),label=document.querySelector(`label[for="${key}"]`),hidden=show||['disk','jets'].includes(object?.type);if(input)input.hidden=hidden;if(label)label.hidden=hidden;}
  if(!show)return;const legacyScale=document.getElementById('editScale'),legacyScaleHeader=document.querySelector('label[for="editScale"]')?.closest('.range-header');if(legacyScale)legacyScale.hidden=true;if(legacyScaleHeader)legacyScaleHeader.hidden=true;const info=r.getStellarInfo?.(id);if(!info)return;
  for(const [key,[property,forward]] of Object.entries(specs)){const n=info[property]??object[property]??0,slider=$('stellar-'+key),exact=$('stellar-'+key+'-exact');if(document.activeElement!==slider)slider.value=forward(n);if(document.activeElement!==exact)exact.value=n;$('stellar-'+key+'-value').textContent=fmt(n);}
  $('stellar-class').value=object.starStyle||'main';$('stellar-cycle').checked=!!object.collapseEnabled;
  const interior=info.interior;$('stellar-interior').hidden=!interior;
  if(interior){$('stellar-interior-total').textContent=`${fmt(info.massSolar)} M☉`;$('stellar-interior-core').textContent=`${fmt(interior.coreMassSolar)} M☉`;$('stellar-interior-envelope').textContent=interior.compatible?`${fmt(interior.envelopeMassSolar)} M☉`:'Outside reference model';$('stellar-interior-radius').textContent=`${fmt(interior.coreRadiusMeters/1000)} km`;$('stellar-interior-note').textContent=interior.compatible?'The mass control includes the core once. The core is centered inside the envelope. Cutaway illumination and its enlarged marker are illustrative; neither changes physical radius, mass, or lensing. Set Envelope opacity to 100% for the exterior.':'These edited mass or radius settings no longer contain the illustrated reference core. Controls remain available for geometric experiments.';}
  for(const [key,value,forward] of [['mass',info.criticalMassSolar,massLog],['radius',info.criticalRadiusMeters,radiusLog]]){const marker=$('stellar-'+key+'-threshold'),slider=$('stellar-'+key),x=(forward(value)-Number(slider.min))/(Number(slider.max)-Number(slider.min));marker.hidden=!Number.isFinite(x)||x<0||x>1||key==='mass'&&info.thresholdReachable===false;marker.style.left=(clamp(x,0,1)*100)+'%';marker.title='Compactness threshold for these mass/radius/spin settings';}
  $('stellar-omega-threshold').hidden=true;
  $('stellar-spin').textContent=`a* = ${fmt(info.spinParameter)} · compactness 2GM/(Rc²) = ${fmt(info.compactness)} · surface |Ω|R/c = ${fmt(info.surfaceSpeedFractionC)}`;
  const nonphysical=info.surfaceSpeedFractionC>=1,massThreshold=info.thresholdReachable===false?'The mass threshold is hidden because it is unreachable at this fixed radius and angular velocity.':`M ≈ ${fmt(info.criticalMassSolar)} M☉.`;
  $('stellar-threshold-note').textContent=`${nonphysical?'Surface rotation reaches or exceeds light speed. This setting is a nonphysical kinematic illustration. ':''}Gold marks: geometric threshold R ≈ ${fmt(info.criticalRadiusMeters)} m; ${massThreshold} Calculated holding the other controls fixed. ${info.canFormKerrHorizon?'This is a compactness comparison, not a stellar-evolution prediction.':'The current angular momentum exceeds the Kerr bound.'}`;
  $('stellar-state').textContent=nonphysical?'NONPHYSICAL ROTATION · KINEMATIC ILLUSTRATION':info.collapsed?'HORIZON FORMED · COMPACT GEOMETRY PROXY':(info.classLabel||'STAR').toUpperCase();

 }
 return{update,dispose(){attachments.dispose();if(raf)cancelAnimationFrame(raf);pending=null;selected=null;for(const key of hiddenGeneric){const input=document.getElementById(key),label=document.querySelector(`label[for="${key}"]`);if(input)input.hidden=false;if(label)label.hidden=false;}mount.remove();}};
}
